import {getAuth} from './auth.mjs';
const host=document.querySelector('#authMount');
try{const clerk=await getAuth();if(clerk.user){location.replace('/index.html');}else{const signup=new URLSearchParams(location.search).get('mode')==='signup'||location.hash==='#signup';host.textContent='';const options={routing:'hash',signInUrl:'/login.html',signUpUrl:'/login.html?mode=signup',forceRedirectUrl:'/index.html',appearance:{variables:{colorPrimary:'#841c29',borderRadius:'0.6rem',fontFamily:'Arial, sans-serif'},elements:{rootBox:{width:'100%'},cardBox:{width:'100%',boxShadow:'none'},card:{boxShadow:'none',backgroundColor:'transparent'}}}};if(signup)clerk.mountSignUp(host,options);else clerk.mountSignIn(host,options);clerk.addListener(({user})=>{if(user)location.replace('/index.html');});}}catch(error){host.textContent=error.message;const a=document.createElement('a');a.href='login.html';a.textContent='Try again';a.className='guest';host.append(a);}
